BEGIN;
CREATE FUNCTION pg_temp.assert_true(v boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'Chef assertion failed: %',label; END IF; END $$;
CREATE FUNCTION pg_temp.reject(q text,pattern text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE q; EXCEPTION WHEN OTHERS THEN IF SQLERRM!~pattern THEN RAISE; END IF; RETURN; END; RAISE EXCEPTION 'Expected Chef rejection'; END $$;
INSERT INTO auth.users(id,email) VALUES('a0000000-0000-4000-8000-000000000011','chef-owner@example.test'),('a0000000-0000-4000-8000-000000000012','chef-peer@example.test');
SELECT pg_temp.assert_true(position('''40001''' in pg_get_functiondef('public.chef_claim_request(uuid,uuid,text,text,uuid,integer)'::regprocedure))=0,'business conflicts never trigger transaction retries');
SELECT pg_temp.assert_true((SELECT count(*)=6 FROM pg_class WHERE relnamespace='public'::regnamespace AND relname IN ('food_memory_state','food_signals','food_memory_tombstones','chef_conversations','chef_messages','chef_requests') AND relrowsecurity),'all Chef tables enforce RLS');
SELECT pg_temp.assert_true(NOT has_function_privilege('authenticated','public.chef_finish_request(uuid,uuid,jsonb,text,uuid,jsonb)','EXECUTE'),'client cannot impersonate model');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000011',true);
SELECT pg_temp.assert_true(NOT public.chef_access(),'closed by default');
SELECT pg_temp.reject($q$SELECT public.food_memory_change('add','b0000000-0000-4000-8000-000000000011',0,'{"attribute":"ingredient","value":"tomat","direction":1}')$q$,'chef_denied');
RESET ROLE;
UPDATE public.kitchen_config SET enabled=true,chef_enabled=true;
SET LOCAL ROLE authenticated;
SELECT public.food_memory_change('add','b0000000-0000-4000-8000-000000000011',0,'{"attribute":"ingredient","value":"tomat","direction":1}');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM public.food_signals),'explicit owner signal');
SELECT pg_temp.reject('DELETE FROM public.food_signals','permission denied');
SELECT pg_temp.reject('SELECT * FROM public.food_memory_tombstones','permission denied');
SELECT pg_temp.reject($q$SELECT public.food_memory_change('add','b0000000-0000-4000-8000-000000000013',0,'{"attribute":"ingredient","value":"allergi","direction":-1}')$q$,'chef_invalid');
SELECT pg_temp.reject($q$SELECT public.chef_claim_request('a0000000-0000-4000-8000-000000000011','b0000000-0000-4000-8000-000000000014','chat',repeat('a',64),'b0000000-0000-4000-8000-000000000015',0)$q$,'permission denied');
SELECT set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000012',true);
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.food_signals),'stranger cannot read');
SELECT pg_temp.reject($q$SELECT public.food_memory_change('forget','b0000000-0000-4000-8000-000000000011',1)$q$,'chef_conflict');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT public.chef_claim_request('a0000000-0000-4000-8000-000000000011','b0000000-0000-4000-8000-000000000014','chat',repeat('a',64),'b0000000-0000-4000-8000-000000000015',0);
SELECT pg_temp.reject($q$SELECT public.chef_claim_request('a0000000-0000-4000-8000-000000000011','b0000000-0000-4000-8000-000000000014','chat',repeat('a',64),'b0000000-0000-4000-8000-000000000015',0)$q$,'chef_request_unavailable');
SELECT public.chef_finish_request('a0000000-0000-4000-8000-000000000011','b0000000-0000-4000-8000-000000000014','{"answer":"Synthetic answer","model":"synthetic","inputTokens":10,"outputTokens":5,"durationMs":1}','Question');
SELECT pg_temp.assert_true((public.chef_claim_request('a0000000-0000-4000-8000-000000000011','b0000000-0000-4000-8000-000000000014','chat',repeat('a',64),'b0000000-0000-4000-8000-000000000015',0)->'cached'->>'answer')='Synthetic answer','replay completed without quota');
SELECT pg_temp.assert_true((SELECT request_count=1 FROM public.ai_rate_limits WHERE function_name='chef:chat'),'one charge');
SELECT pg_temp.reject($q$SELECT public.chef_claim_request('a0000000-0000-4000-8000-000000000012','b0000000-0000-4000-8000-000000000014','chat',repeat('a',64),'b0000000-0000-4000-8000-000000000015',0)$q$,'chef_conflict');
SELECT public.chef_claim_request('a0000000-0000-4000-8000-000000000011','b0000000-0000-4000-8000-000000000016','chat',repeat('b',64),'b0000000-0000-4000-8000-000000000015',1);
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000011',true);
SELECT pg_temp.assert_true((SELECT count(*)=2 FROM public.chef_messages),'saved exchange');
SELECT public.food_memory_change('forget','b0000000-0000-4000-8000-000000000011',1);
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.chef_messages),'forget clears stale chat');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.food_signals),'forget removes raw evidence');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM public.food_memory_tombstones),'hashed reconstruction barrier');
SELECT pg_temp.reject($q$SELECT public.chef_finish_request('a0000000-0000-4000-8000-000000000011','b0000000-0000-4000-8000-000000000016','{"answer":"stale"}','old')$q$,'chef_conflict');
RESET ROLE;
-- Source-bound extraction and forgetting/reset barriers.
INSERT INTO public.kitchen_recipes(id,user_id) VALUES('c0000000-0000-4000-8000-000000000011','a0000000-0000-4000-8000-000000000011');
INSERT INTO public.kitchen_recipe_versions(id,recipe_id,user_id,revision,document) VALUES('c0000000-0000-4000-8000-000000000012','c0000000-0000-4000-8000-000000000011','a0000000-0000-4000-8000-000000000011',1,
 '{"title":"Soup","description":"","servings":2,"totalMinutes":10,"image":"none","sourceNote":"","notes":"","ingredients":[{"id":"c0000000-0000-4000-8000-000000000014","name":"Tomat","amount":1,"unit":"pcs"}],"steps":[{"id":"c0000000-0000-4000-8000-000000000015","title":"Cook","text":"Cook","timerSeconds":null}]}');
INSERT INTO public.cooking_sessions(id,user_id,recipe_version_id,revision,state,last_request_id) VALUES('c0000000-0000-4000-8000-000000000013','a0000000-0000-4000-8000-000000000011','c0000000-0000-4000-8000-000000000012',1,'{"status":"completed","activeStep":0,"servings":2,"checkedIngredientIds":[],"timers":[]}',gen_random_uuid());
INSERT INTO public.cooking_feedback(id,user_id,session_id,note) VALUES('c0000000-0000-4000-8000-000000000016','a0000000-0000-4000-8000-000000000011','c0000000-0000-4000-8000-000000000013','Jag gillar tomat och basilika.');
SET LOCAL ROLE service_role;
SELECT public.chef_claim_request('a0000000-0000-4000-8000-000000000011','d0000000-0000-4000-8000-000000000011','extract',repeat('c',64));
SELECT pg_temp.assert_true((public.chef_finish_request('a0000000-0000-4000-8000-000000000011','d0000000-0000-4000-8000-000000000011','{"model":"synthetic"}','','c0000000-0000-4000-8000-000000000016','[{"attribute":"ingredient","value":"tomat","direction":1,"quote":"Jag gillar tomat"},{"attribute":"ingredient","value":"basilika","direction":1,"quote":"basilika"}]')->>'candidateCount')::integer=1,'forgotten value not re-extracted');
SELECT pg_temp.assert_true((SELECT status='pending' FROM public.food_signals),'AI never confirms');
SELECT public.chef_claim_request('a0000000-0000-4000-8000-000000000011','d0000000-0000-4000-8000-000000000012','extract',repeat('d',64));
SELECT pg_temp.reject($q$SELECT public.chef_finish_request('a0000000-0000-4000-8000-000000000011','d0000000-0000-4000-8000-000000000012','{}','','c0000000-0000-4000-8000-000000000016','[{"attribute":"ingredient","value":"salt","direction":1,"quote":"not in source"}]')$q$,'chef_invalid');
SELECT public.reset_privacy_memory('a0000000-0000-4000-8000-000000000011');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.food_signals),'privacy reset includes food');
SELECT pg_temp.assert_true((SELECT reset_at>='2026-01-01' FROM public.food_memory_state),'reset source cutoff');
SELECT public.chef_claim_request('a0000000-0000-4000-8000-000000000011','d0000000-0000-4000-8000-000000000013','extract',repeat('e',64));
SELECT pg_temp.reject($q$SELECT public.chef_finish_request('a0000000-0000-4000-8000-000000000011','d0000000-0000-4000-8000-000000000013','{}','','c0000000-0000-4000-8000-000000000016','[]')$q$,'chef_invalid');
RESET ROLE;
SELECT public.request_account_erasure('a0000000-0000-4000-8000-000000000011');
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert_true(NOT public.chef_access(),'erasure revokes old JWT access');
RESET ROLE;
DELETE FROM auth.users WHERE id='a0000000-0000-4000-8000-000000000011';
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.chef_requests),'erasure cascades requests');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.food_memory_state),'erasure cascades epoch');
SET LOCAL ROLE anon;
SELECT pg_temp.reject('SELECT * FROM public.food_signals','permission denied');
SELECT pg_temp.reject('SELECT public.chef_access()','permission denied');
RESET ROLE;
ROLLBACK;
SELECT 'chef_memory_acceptance_passed';
